-- Localities and counties without diacritics, everywhere: "Timișoara" / "Timisoara" / "Timişoara" become one
-- ("Timisoara"), so filters, groupings and statistics count them together.
-- 1. The values as they were, to undo if ever needed (table, row, column, old value).
CREATE TABLE IF NOT EXISTS locality_backup (
  tbl        TEXT NOT NULL,
  row_id     TEXT NOT NULL,
  col        TEXT NOT NULL,
  old_value  TEXT,
  saved_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

INSERT INTO locality_backup (tbl, row_id, col, old_value) SELECT 'crm_properties', id, 'city', city FROM crm_properties WHERE city IS NOT NULL AND city <> TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(city, 'ă', 'a'), 'â', 'a'), 'î', 'i'), 'ș', 's'), 'ş', 's'), 'ț', 't'), 'ţ', 't'), 'Ă', 'A'), 'Â', 'A'), 'Î', 'I'), 'Ș', 'S'), 'Ş', 'S'), 'Ț', 'T'), 'Ţ', 'T'));
INSERT INTO locality_backup (tbl, row_id, col, old_value) SELECT 'crm_properties', id, 'county', county FROM crm_properties WHERE county IS NOT NULL AND county <> TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(county, 'ă', 'a'), 'â', 'a'), 'î', 'i'), 'ș', 's'), 'ş', 's'), 'ț', 't'), 'ţ', 't'), 'Ă', 'A'), 'Â', 'A'), 'Î', 'I'), 'Ș', 'S'), 'Ş', 'S'), 'Ț', 'T'), 'Ţ', 'T'));
INSERT INTO locality_backup (tbl, row_id, col, old_value) SELECT 'entities', id, 'city', city FROM entities WHERE city IS NOT NULL AND city <> TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(city, 'ă', 'a'), 'â', 'a'), 'î', 'i'), 'ș', 's'), 'ş', 's'), 'ț', 't'), 'ţ', 't'), 'Ă', 'A'), 'Â', 'A'), 'Î', 'I'), 'Ș', 'S'), 'Ş', 'S'), 'Ț', 'T'), 'Ţ', 'T'));
INSERT INTO locality_backup (tbl, row_id, col, old_value) SELECT 'entities', id, 'county', county FROM entities WHERE county IS NOT NULL AND county <> TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(county, 'ă', 'a'), 'â', 'a'), 'î', 'i'), 'ș', 's'), 'ş', 's'), 'ț', 't'), 'ţ', 't'), 'Ă', 'A'), 'Â', 'A'), 'Î', 'I'), 'Ș', 'S'), 'Ş', 'S'), 'Ț', 'T'), 'Ţ', 'T'));
INSERT INTO locality_backup (tbl, row_id, col, old_value) SELECT 'orders', id, 'city', city FROM orders WHERE city IS NOT NULL AND city <> TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(city, 'ă', 'a'), 'â', 'a'), 'î', 'i'), 'ș', 's'), 'ş', 's'), 'ț', 't'), 'ţ', 't'), 'Ă', 'A'), 'Â', 'A'), 'Î', 'I'), 'Ș', 'S'), 'Ş', 'S'), 'Ț', 'T'), 'Ţ', 'T'));
INSERT INTO locality_backup (tbl, row_id, col, old_value) SELECT 'partners', id, 'city', city FROM partners WHERE city IS NOT NULL AND city <> TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(city, 'ă', 'a'), 'â', 'a'), 'î', 'i'), 'ș', 's'), 'ş', 's'), 'ț', 't'), 'ţ', 't'), 'Ă', 'A'), 'Â', 'A'), 'Î', 'I'), 'Ș', 'S'), 'Ş', 'S'), 'Ț', 'T'), 'Ţ', 'T'));
