  UPDATE users SET city = TRIM(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(city, 'ă', 'a'), 'â', 'a'), 'î', 'i'), 'ș', 's'), 'ş', 's'), 'ț', 't'), 'ţ', 't'), 'Ă', 'A'), 'Â', 'A'), 'Î', 'I'), 'Ș', 'S'), 'Ş', 'S'), 'Ț', 'T'), 'Ţ', 'T')) WHERE rowid = NEW.rowid;
END;
